public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes cover of a video story. Can be called only if story.can_be_edited == true and the story isn't being edited now
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> EditStoryCoverAsync(long storyPosterChatId = default, int storyId = default, double? coverFrameTimestamp = default)
    {

           using var activity =  StartCallActivity("EditStoryCoverAsync", typeof(EditStoryCover).FullName ?? "EditStoryCoverAsync");

           try
           {
             return client.EditStoryCoverAsync(storyPosterChatId, storyId, coverFrameTimestamp);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
